import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://127.0.0.1:4173/products.html');
const data = await page.evaluate(() => {
  const card = document.querySelector('.card.product');
  const badge = card.querySelector('.badge');
  const thumb = card.querySelector('.card-thumb');
  const cs = getComputedStyle(card);
  const bs = getComputedStyle(badge);
  const r = (el) => { const b = el.getBoundingClientRect(); return {x:b.x,y:b.y,w:b.width,h:b.height}; };
  return {
    card: r(card), badge: r(badge), thumb: r(thumb),
    cardOverflow: cs.overflow, cardRadius: cs.borderRadius, cardBorder: cs.border,
    badgePos: bs.position, badgeTop: bs.top, badgeRight: bs.right,
    badgeBg: bs.backgroundColor, badgeFont: bs.fontFamily, badgeFontSize: bs.fontSize,
    badgePad: bs.padding,
  };
});
console.log(JSON.stringify(data, null, 2));
await browser.close();
